  ('c81af320-eaaa-424d-86a6-3ebc69ad75a7', '261d849f-0408-4d56-8009-1adde28feda6', null, 'topic'::public.curated_course_node_type, 'Biology as a Scientific Discipline', 'General Biology I should begin by teaching students how biologists ask questions, evaluate evidence, and build explanations from observations and experiments.', 0),
